int main() {
    int n;

    while(scanf("%d", &n), n) {
        int max_p = 0, max_d = 0;

        for (int i = 0; i < n; ++i) {
            int p, d1, d2;
            scanf("%d %d %d", &p, &d1, &d2);

            int current_d = d1 + d2;
            if (current_d > max_d) {
                max_p = p;
                max_d = current_d;
            }
        }

        printf("%d %d\n", max_p, max_d);
    }
}

