#include <cstdio>
#include <tuple>

std::tuple<int, int> findMax(int n) {
    int max_p = -1, max_d = 0;
    for (; n; n--) {
        int p, d1, d2;
        scanf("%d %d %d", &p, &d1, &d2); // Combined input read

        if (d1 + d2 > max_d)
            max_p = p, max_d = d1 + d2;
    }
    return {max_p, max_d};
}

int main() {
    int n;

    while (scanf("%d", &n), n) {
        auto [max_p, max_d] = findMax(n);
        printf("%d %d\n", max_p, max_d);
    }
}

